use super::prelude::*;
use crate::cards::spec_index::card_pod_from_id;

/// Mad Science (colorless, Event) — a "TinkerTime" multi-mode card. Its mode
/// (`CardType` Attack/Skill/Power) and `RiderEffect` are chosen by the
/// TinkerTime event (`sts2-rs-6ynt.4`, deferred) and stored per-instance via
/// [`set_mad_science_variant`]. Mirrors
/// `MegaCrit.Sts2.Core.Models.Cards/MadScience.cs::OnPlay` (v0.103.2):
///
/// - **Attack**: `ViolenceHits` (3 if rider == Violence, else 1) × 12 damage
///   (`ExecuteAttack`).
/// - **Skill**: gain 8 block (`MAD_SCIENCE_SKILL_BLOCK`, `ExecuteSkill`).
/// - **Power** (`ExecutePower`): Expertise → Strength +2 & Dexterity +2;
///   Curious → Curious +1; Improvement → Improvement +1 (all on self).
/// - then the **shared rider** (`ExecuteRider`, fired for Sapping / Choking /
///   Energized / Wisdom / Chaos): Sapping → Weak 2 + Vulnerable 2 on target;
///   Choking → Strangle 6 on target; Energized → +2 energy; Wisdom → draw 3;
///   Chaos → generate one distinct card from the owner's character pool
///   (`CardFactory.GetDistinctForCombat`, `Rng.CombatCardGeneration`), set it
///   free this turn, and add it to hand.
///
/// The TinkerTime event (`sts2-rs-2guyj`, `events::shared_wave_b`) selects
/// mode/rider and grants a moded card; the morph is packed into the
/// master_deck card's `VarKey::Generic` slot and is run-persistent (deck
/// cards are cloned fresh into each combat and never reset on the run side).
/// A MadScience obtained any other way (default-constructed) is still
/// Attack / no rider → 12 damage.
pub(crate) fn play_mad_science(
    state: &mut CombatState,
    target: Option<CreatureUid>,
) -> EffectResult {
    let (mode, rider) = mad_science_variant(state);

    match mode {
        CardType::Skill => {
            let _ = gain_block_player(state, MAD_SCIENCE_SKILL_BLOCK);
        }
        CardType::Power => {
            if let Some(p) = state.player.creature_uid {
                match rider {
                    TinkerTimeRider::Expertise => {
                        apply_power_to_creature(state, p, PowerKind::Strength, 2);
                        apply_power_to_creature(state, p, PowerKind::Dexterity, 2);
                    }
                    TinkerTimeRider::Curious => {
                        apply_power_to_creature(state, p, PowerKind::Curious, 1);
                    }
                    TinkerTimeRider::Improvement => {
                        apply_power_to_creature(state, p, PowerKind::Improvement, 1);
                    }
                    _ => {}
                }
            }
        }
        // Attack (default) — and any non-Skill/Power fallback.
        _ => {
            let hits = if rider == TinkerTimeRider::Violence {
                3
            } else {
                1
            };
            // v0.107.1 issues one `DamageCmd.Attack` PER hit
            // (`MadScience.cs:216-225`), so each hit is its own command:
            // Vigor/Gigantification boost the first and are spent by its
            // `AfterAttack` before the next. v0.111.0 issues one command
            // `.WithHitCount(hits)`, boosting every hit.
            let per_hit_commands = state.game_version < sts2_core::GameVersion::V0_111_0;
            let card = sts2_core::card_effects::resolving_card_uid(state);
            if let Some(t) = target {
                let damage = current_damage(state);
                for _ in 0..hits {
                    let _ = deal_damage_player_to_enemy(state, t, damage);
                    if per_hit_commands {
                        if let Some(card) = card {
                            sts2_core::hooks::end_player_attack_command(state, card);
                        }
                    }
                }
            }
        }
    }

    // Shared rider effects — C# `ExecuteRider` (Sapping / Choking / Energized /
    // Wisdom / Chaos). Violence is consumed by ExecuteAttack's hit count and
    // Expertise/Curious/Improvement by ExecutePower, so they no-op here.
    match rider {
        TinkerTimeRider::Sapping => {
            if let Some(t) = target {
                apply_power_to_creature(state, t, PowerKind::Weak, 2);
                apply_power_to_creature(state, t, PowerKind::Vulnerable, 2);
            }
        }
        TinkerTimeRider::Choking => {
            if let Some(t) = target {
                apply_power_to_creature(state, t, PowerKind::Strangle, 6);
            }
        }
        TinkerTimeRider::Energized => state.gain_energy(2),
        TinkerTimeRider::Wisdom => {
            let _ = sts2_core::cards::draw_via_state(state, 3);
        }
        // C# `ExecuteRider` Chaos arm (MadScience.cs:280-285): draw one
        // distinct card from the owner's CHARACTER pool off
        // `Rng.CombatCardGeneration` — `CardFactory.GetDistinctForCombat(Owner,
        // Owner.Character.CardPool.GetUnlockedCards(...), 1,
        // Rng.CombatCardGeneration).First()` — set it free this turn, and add
        // it to hand. The character pool + `combat_card_generation`
        // whole-pool shuffle + take-1 (with `FilterForCombat` applied) is the
        // same surface Discovery uses (`distinct_character_card_ids`). We stamp
        // `FreeThisTurn` on the POD *before* spawning so the
        // `after_card_entered_combat` listeners observe the free card, matching
        // C#'s `SetToFreeThisTurn()`-then-`CardPileCmd.Add` order.
        TinkerTimeRider::Chaos => {
            if let Some(character) = state.player.character {
                let ids = distinct_character_card_ids(state, character, None, 1);
                if let Some(&card_id) = ids.first() {
                    if let Some(mut card) = card_pod_from_id(card_id, false) {
                        card.set_combat_var(VarKey::FreeThisTurn, 1);
                        if state.game_version >= sts2_core::GameVersion::V0_111_0 {
                            // v0.111.0 MadScience.cs:286 —
                            // `AddGeneratedCardToCombat(card, Hand, Owner)`:
                            // recorded in `History.CardGenerated` (Supermassive's
                            // count, loadout Regent 5045) and fires
                            // `AfterCardGeneratedForCombat` (Regalite, Arsenal, ...).
                            let _ = sts2_core::card_effects::spawn_card_into_hand_with_origin(
                                state, card, true,
                            );
                        } else {
                            // v0.107.1 MadScience.cs:288 — a plain
                            // `CardPileCmd.Add(cardModel, Hand)`: no generation hooks.
                            sts2_core::card_effects::add_new_card_to_hand(state, card);
                        }
                    }
                }
            }
        }
        TinkerTimeRider::None
        | TinkerTimeRider::Violence
        | TinkerTimeRider::Expertise
        | TinkerTimeRider::Curious
        | TinkerTimeRider::Improvement => {}
    }
    EffectResult::Resolved
}
